class Solution { public:
 long long minimumOperations(vector<int>& nums,vector<int>& target) {
  long long ans=0,prev=0;
  for(int i=0;i<(int)nums.size();++i) { long long d=(long long)target[i]-nums[i];
   if(d>0) ans+=max(0LL,d-max(0LL,prev));
   else if(d<0) ans+=max(0LL,-d-max(0LL,-prev));
   prev=d;
  } return ans;
 }
};
